def transform(grid):
    h, w = len(grid), len(grid[0])

    # A uniform horizontal line identifies the separator color.
    uniform_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    if uniform_rows:
        sep = grid[uniform_rows[0]][0]
    else:
        uniform_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
        if not uniform_cols:
            return [row[:] for row in grid]
        sep = grid[0][uniform_cols[0]]

    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def groups(size, separators):
        result, start = [], 0
        for p in separators:
            result.append(list(range(start, p)))
            start = p + 1
        result.append(list(range(start, size)))
        return [g for g in result if g]

    row_groups = groups(h, sep_rows)
    col_groups = groups(w, sep_cols)

    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get) if counts else sep

    regions = []
    for rs in row_groups:
        for cs in col_groups:
            cells = [[grid[r][c] for c in cs] for r in rs]
            detail = sum(v != bg and v != sep for row in cells for v in row)
            if detail:
                regions.append((detail, rs, cs, cells))

    if not regions:
        return [row[:] for row in grid]

    _, src_rs, src_cs, pattern = max(regions, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for rs in row_groups:
        for cs in col_groups:
            if len(rs) == len(src_rs) and len(cs) == len(src_cs):
                for i, r in enumerate(rs):
                    for j, c in enumerate(cs):
                        out[r][c] = pattern[i][j]
    return out
